# 輾轉相除
def continued_fraction(a, b):
    while b:
        yield a // b
        a, b = b, a % b

# k / d 的候選值
def k_d(cf):
    p0, p1 = 0, 1
    q0, q1 = 1, 0

    for a in cf:
        p0, p1 = p1, a * p1 + p0
        q0, q1 = q1, a * q1 + q0

        yield p1, q1

def wiener(e, N):
    for k, d in k_d(continued_fraction(e, N)):

        if k == 0:
            continue
        if (e * d - 1) % k != 0:
            continue
        phi = (e * d - 1) // k

        # p + q = N - phi + 1
        s = N - phi + 1

        # x² - sx + N = 0
        delta = s * s - 4 * N

        if delta < 0:
            continue

        root = isqrt(delta)
        if root * root == delta:
            p = (s + root) // 2
            q = (s - root) // 2

            if p * q == N:
                return d
    return None

